import React from 'react';
import ReactDOM from 'react-dom';
import styled from '@emotion/styled';


interface searchFilterItemType {
    text:string;
}

const SearchFilterItem:React.FC<searchFilterItemType> = ({text}) => {
    const ItemWrap = styled.div`
        display: flex;
        justify-content: center;
        align-items: center;

        border-radius: 50px;
        background-color: gray;
        width: auto;
        height: 10px;

        /* 내부요소 클릭 X */
        pointer-events: none;

        padding: 10px;
        margin: 0 5px;
    `;
    const ItemText = styled.span`
    
    `;
    
    const ItemRemoveButton = styled.button`
        border: none;
        background-color: rgba(0,0,0,0);
        box-shadow: none;

        padding: 0 10px;
        margin: 0;
    `;

    return(
        <ItemWrap>
            <ItemText>{text}</ItemText>
            <ItemRemoveButton>X</ItemRemoveButton>
        </ItemWrap>
    );
}

export default SearchFilterItem;