import React from 'react';
import styled from '@emotion/styled';

const SearchWrapper: React.FC = ({children}) => {
    const Wrapper = styled.div`
        display: flex;
        justify-content: center;
        align-items: center;

        width: 100%;
        height: auto;

        border-radius: 50px;

        background-color: gray;
    `;

    return(
    <Wrapper>
        {children}
    </Wrapper>)
}

export default SearchWrapper;