import React from 'react';
import styled from '@emotion/styled';

interface LogoWrapperType{
    myStyle?: {
        width?:string;
        height?:string;
    };
}

const LogoWrapper: React.FC<LogoWrapperType> = ({children, myStyle={width:"300px", height:"300px"}}) => {
    const {width, height} = myStyle;
    const Wrapper = styled.div`
        width: ${width};
        height: ${height};

        display: flex;
        justify-content: center;
    `;

    return(
    <Wrapper>
        {children}
    </Wrapper>)
}

export default LogoWrapper;