import React from 'react';
import styled from '@emotion/styled';
import {Link} from 'react-router-dom';

interface logoType {
    imgPath: string;
}

const Logo: React.FC<logoType> = ({imgPath}) => {
    const LogoImg = styled.img`
        width: auto;
        height: 100%;
    `;

    return <Link to="/"><LogoImg alt="Logo Image" src={imgPath}/></Link>
}

export default Logo;