import React from 'react';
import styled from '@emotion/styled';
import {Logo, LogoWrapper} from '../../components/logo';
import {SearchWrapper, SearchInput} from '../../components/search';
import { SearchFilterItem, SearchFilterWrapper } from '../../components/search-filter';
import {useCookies} from 'react-cookie';
import { useEffect } from 'react';
import { useState } from 'react';

const MainHeader = () => {
    const [cookies, setCookies] = useCookies(['filer']);
    const [filterItems, setFilterItems] = useState<never[]>([]);
    useEffect(()=> {
        if(cookies?.filer !== undefined){
            setFilterItems(cookies.filer);
        }
    }, [filterItems]);


    const MainHeaderWrapper = styled.div`
        display: grid;
        width: 100vw;
        height: 200px;

        grid-template-rows: 1fr 1fr 1fr;
        grid-template-columns: 1fr 1fr 1fr 1fr 1fr 1fr;

        border-bottom: 1px solid gray;

        /* Logo */
        & > div:nth-of-type(1){
            grid-row: 1/3;
            grid-column: 1/3;
        }
        /* Title */
        & > div:nth-of-type(2){
            grid-row: 1/2;
            grid-column: 3/7;
        }
        /* Search */
        & > div:nth-of-type(3){
            grid-row: 2/3;
            grid-column: 3/6;
        }
        /* Search Filter */
        & > div:nth-of-type(4){
            grid-row: 3/4;
            grid-column: 1/7;
        }
    `;

    const MainHeaderTitleWrapper = styled.div`
        
    `;

    const MainHeaderTitle = styled.h2`
    
    `;

    return (
    <MainHeaderWrapper>
        <LogoWrapper myStyle={{width: "100%", height: "100%"}}>
            <Logo imgPath="/logo.png"></Logo>
        </LogoWrapper>
        <MainHeaderTitleWrapper>
            <MainHeaderTitle>BeeImp의 석사 논문 작성을 위한 참조 논문 정리</MainHeaderTitle>
        </MainHeaderTitleWrapper>
        <SearchWrapper>
            <SearchInput></SearchInput>
        </SearchWrapper>
        <SearchFilterWrapper>
            <SearchFilterItem text={"SDN"}></SearchFilterItem>
            <SearchFilterItem text={"SDP"}></SearchFilterItem>
            <SearchFilterItem text={"Security"}></SearchFilterItem>
        </SearchFilterWrapper>
    </MainHeaderWrapper>
    );
}

export default MainHeader;